// ==========================================
// Constrói o Payload JWT
// ==========================================
// Transforma dados do MySQL em payload JWT RFC 7519
// com claims customizados para multi-tenancy

const user = $input.first().json;
const now = Math.floor(Date.now() / 1000);

// Gerar UUID v4 para jti (JWT ID)
function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

return {
  json: {
    code: 200,
    data: {
      senha_hash: user.password,
      payload: {
        // Registered Claims (RFC 7519)
        sub: user.id,                    // Subject: ID do usuário
        iss: 'ciacuidadores',              // Issuer: Emissor do token
        aud: 'primecare',                  // Audience: Destinatário
        exp: now + (24 * 60 * 60),         // Expiration: 24 horas
        iat: now,                          // Issued At: timestamp criação
        jti: generateUUID(),               // JWT ID: identificador único

        // Custom Claims
        tenant: user.tenant_array,       // Multi-tenancy: array de tenants
        roles: [user.role_name],         // Papéis do usuário
        name: user.name,                 // Nome de exibição
        email: user.email                // Email
      }
    }
  }
};

