return $input.all();

// ==========================================
// Converte Hash PHP para Node.js
// ==========================================
// PHP usa $2y$ no bcrypt
// Node.js usa $2a$ no bcrypt
// Algoritmos idênticos, apenas prefixo difere
const records = [];

for (const item of $input.all()) {
  const json = item.json;
  const data = item.json.data;
  data.senha_hash = data.senha_hash.replace(/^\$2y\$/, '$2a$')

  records.push({ ...json, data })
}

return records;
